import { SheetBody } from '../../slots/defs/sheet';
import { useClaims } from '../claims/claims';
import { personDueTotal, useRates } from '../rates/rates';
import { useFloor, useLate } from '../settings/settings';
import { usePersonCap } from '../pools/pools';
import { useSheetToday } from '../sheet/sheet';
import { gradeOn, usePeople } from './people';

/** A CSV value: wrapped in double quotes (any quote inside doubled) when it holds a comma, a quote or a line
 *  break, else as it is. */
function csvValue(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

/** The button that downloads the people as a CSV file: a header line, then one line per person in list order,
 *  retired people included, with their grade in force on the sheet's today, the date they are retired from (or
 *  nothing) and their due-total as shown on their row; each line ends with a line feed. */
function ExportPeople({ sheetId }: { sheetId: string; user: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const capOf = usePersonCap(sheetId);

  const download = () => {
    const lines = [
      ['name', 'grade', 'retired-from', 'due-total'],
      ...people.map((p) => [
        p.name,
        gradeOn(p, today),
        p.retiredFrom ?? '',
        personDueTotal(p, claims, rates, today, floor, late, capOf(p.id), people),
      ]),
    ];
    const csv = lines.map((values) => values.map(csvValue).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = `people-${sheetId}.csv`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 0);
  };

  return (
    <p>
      <button type="button" data-testid="export-people" onClick={download}>
        Export people (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetBody.fill({ order: 11, Component: ExportPeople });
import { SheetBody } from '../../slots/defs/sheet';
import { gradeOn, usePeople } from '../people/people';
import { periodOf, usePeriods } from '../periods/periods';
import { claimDue, rateOn, useRates } from '../rates/rates';
import { useFloor, useLate } from '../settings/settings';
import { dueBy, useClaims } from './claims';

/** A CSV value: wrapped in double quotes (any quote inside doubled) when it holds a comma, a quote or a line
 *  break, else as it is (as the people export writes it). */
function csvValue(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

/** The button that downloads the claims as a CSV file: a header line, then one line per claim, people in list order
 *  (retired people included) and each person's claims oldest first, with its person's name, number (or nothing),
 *  date, amount, due, status and period (or nothing) as its row shows them; each line ends with a line feed. */
function ExportClaims({ sheetId }: { sheetId: string; user: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const periods = usePeriods(sheetId).data ?? [];
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);

  const download = () => {
    const lines = [
      ['person', 'number', 'date', 'amount', 'due', 'status', 'period'],
      // The claims come newest first: each person's are reversed to oldest first.
      ...people.flatMap((p) => claims.filter((c) => c.personId === p.id).reverse().map((c) => [
        p.name,
        c.number ?? '',
        c.date,
        c.amount,
        claimDue(c, rateOn(rates, gradeOn(p, c.date), c.date, c.id), floor, late),
        c.status,
        periodOf(periods, dueBy(c))?.name ?? '',
      ])),
    ];
    const csv = lines.map((values) => values.map(csvValue).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = `claims-${sheetId}.csv`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 0);
  };

  return (
    <p>
      <button type="button" data-testid="export-claims" onClick={download}>
        Export claims (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetBody.fill({ order: 11.1, Component: ExportClaims });
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx response: its status and the text the server sent with it. */
export class HttpError extends Error {
  constructor(
    message: string,
    readonly status: number,
    readonly body: string,
  ) {
    super(message);
  }
}

/** The date this screen shows the sheet as of ('' when it shows it as it is now): every read asks for the sheet as
 *  of it (?asOf=), and every change is sent marked with it (X-As-Of), so the server refuses it. Kept in step with
 *  the URL's asOf by features/sheet/asof; read from the URL at start-up so the first reads already carry it. */
let asOf = typeof window === 'undefined' ? '' : new URLSearchParams(window.location.search).get('asOf') ?? '';

export function setRequestAsOf(date: string): void {
  asOf = date;
}

/** The date this screen previews the sheet's today as ('' when none): every read asks for the sheet's current records
 *  figured on it (?preview=); changes are sent unmarked, made on the sheet's real today. Kept in step with the URL's
 *  preview by features/sheet/preview; read from the URL at start-up so the first reads already carry it. */
let preview = typeof window === 'undefined' ? '' : new URLSearchParams(window.location.search).get('preview') ?? '';

export function setRequestPreview(date: string): void {
  preview = date;
}

function withParam(path: string, key: string, value: string): string {
  return value === '' ? path : `${path}${path.includes('?') ? '&' : '?'}${key}=${encodeURIComponent(value)}`;
}

function withAsOf(path: string): string {
  return withParam(withParam(path, 'asOf', asOf), 'preview', preview);
}

function changeHeaders(): Record<string, string> {
  return asOf === '' ? { 'Content-Type': 'application/json' } : { 'Content-Type': 'application/json', 'X-As-Of': asOf };
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status, await res.text());
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(withAsOf(path));
}

/** A read of the store as it is now, whatever date this screen shows the sheet as of. */
export function getJsonNow<T>(path: string): Promise<T> {
  return send<T>(path);
}

