import { useQueryClient } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheet';
import { poolsKey } from './pools';
import type { Pool } from './pools';

/** A CSV value: wrapped in double quotes (any quote inside doubled) when it holds a comma, a quote or a line
 *  break, else as it is. */
function csvValue(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

/** The button that downloads the pools as a CSV file: a header line, then one line per member, pools in the order
 *  added and members in the order added, a member pool as pool:<name>, and the cut as shown on the pool (empty when
 *  none); each line ends with a line feed. The pools are re-read first, so the file matches the store. */
function ExportPools({ sheetId }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();

  const download = async () => {
    const pools = await queryClient.fetchQuery({
      queryKey: poolsKey(sheetId),
      queryFn: () => getJson<Pool[]>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`),
      staleTime: 0,
    });
    const lines = [
      ['pool', 'member', 'share', 'cut'],
      ...pools.flatMap((p) =>
        p.members.map((m) => [p.name, m.poolId !== null ? `pool:${m.name}` : m.name, m.share, m.cut]),
      ),
    ];
    const csv = lines.map((values) => values.map(csvValue).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = `pools-${sheetId}.csv`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 0);
  };

  return (
    <p>
      <button type="button" data-testid="export-pools" onClick={() => void download()}>
        Export pools (CSV)
import { PersonRow } from '../../slots/defs/personRow';
import { useClaims } from '../claims/claims';
import type { Person } from '../people/people';

/** A CSV value: wrapped in double quotes (any quote inside doubled) when it holds a comma, a quote or a line
 *  break, else as it is (as the claims export writes it). */
function csvValue(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

/** The button that downloads a person's statement as a CSV file: a header line, then one line per claim of theirs
 *  their last statement bound, oldest first, with its number (or nothing), date, amount, the figure the statement
 *  bound it to as the claim shows it (n/a when it bound none) and status; each line ends with a line feed. */
function PersonExportStatement({ sheetId, person }: { sheetId: string; user: string; person: Person }) {
  const claims = useClaims(sheetId).data ?? [];

  const download = () => {
    const lines = [
      ['number', 'date', 'amount', 'figure', 'status'],
      // The claims come newest first: they are reversed to oldest first.
      ...claims.filter((c) => c.personId === person.id && c.stated).reverse().map((c) => [
        c.number ?? '',
        c.date,
        c.amount,
        c.statedDue ?? 'n/a',
        c.status,
      ]),
    ];
    const csv = lines.map((values) => values.map(csvValue).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = `statement-${sheetId}-${person.id}.csv`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 0);
  };

  return (
    <td>
      <button type="button" data-testid="person-export-statement" onClick={download}>
        Export statement (CSV)
      </button>
    </td>

